mapper.select:

select t.PORTFOLIO_ID id,m.PORTFOLIO_NAME name,m.PROFIT_TYPE pId,m.RISK_ENABLED object
 from PA_PTL_PORTFOLIO t
 inner join  PTL_PORTFOLIO m
 on t.PORTFOLIO_ID=m.PORTFOLIO_ID



		t.PORTFOLIO_ID not in (select PORTFOLIO_ID from RSK_PORTFOLIO_INDICATOR where PORTFOLIO_LEVEL =#{portfLevel} and IND_ID =#{indId} )


		and (m.PORTFOLIO_NAME LIKE CONCAT_ws('', '%',#{portfName}, '%')
		or m.PORTFOLIO_ID like CONCAT_ws('', '%',#{portfName}, '%'))


		and m.PROFIT_TYPE = #{profitType}


		and t.OPEN_TYPE = #{issueMode}


		and t.RAISE_TYPE = #{raiseType}


		and t.INVEST_NATURE = #{investType}

	and m.PORTFOLIO_TYPE in ('01','02') and  m.MDATE  >=  STR_TO_DATE(#{platDate},'%Y-%m-%d')

 	select t.PORTFOLIO_ID id,m.PORTFOLIO_NAME name,${fields} as pId,m.RISK_ENABLED object
	 from PA_PTL_PORTFOLIO t
	 inner join  PTL_PORTFOLIO m
	 on t.PORTFOLIO_ID=m.PORTFOLIO_ID


			t.PORTFOLIO_ID not in (select PORTFOLIO_ID from RSK_PORTFOLIO_INDICATOR where PORTFOLIO_LEVEL =#{portfLevel} and IND_ID =#{indId} )


			and (m.PORTFOLIO_NAME LIKE CONCAT_ws('', '%',#{portfName}, '%')
			or m.PORTFOLIO_ID like CONCAT_ws('', '%',#{portfName}, '%'))


			and m.PROFIT_TYPE = #{profitType}


			and t.OPEN_TYPE = #{issueMode}


			and t.RAISE_TYPE = #{raiseType}


			and t.INVEST_NATURE = #{investType}

		and m.PORTFOLIO_TYPE in ('01','02') and m.MDATE  >=  STR_TO_DATE(#{platDate},'%Y-%m-%d')
